import {emptyMaze,connect,neighbors} from '../../src/core/maze';
import {withPortals} from '../../src/core/portals';
import {freeCellLayout} from './free-cell-layout';
export function freeLoopTrapFixture(){const m=emptyMaze({columns:9,rows:9,corridorWidth:2,algorithm:'prim',seed:'loop',extraConnections:1,shape:{kind:'grid-rectangles',rectangles:[{x:2,z:3,width:6,height:6,operation:'add'},{x:3,z:4,width:4,height:4,operation:'subtract'},{x:0,z:3,width:2,height:1,operation:'add'},{x:2,z:1,width:1,height:2,operation:'add'},{x:0,z:1,width:2,height:1,operation:'add'},{x:0,z:0,width:1,height:1,operation:'add'},{x:2,z:2,width:6,height:1,operation:'add'},{x:0,z:1,width:8,height:1,operation:'add'}]}});const c=(x:number,z:number)=>z*9+x,ring:number[]=[];for(let x=2;x<7;x++)ring.push(c(x,3));for(let z=3;z<8;z++)ring.push(c(7,z));for(let x=7;x>2;x--)ring.push(c(x,8));for(let z=8;z>3;z--)ring.push(c(2,z));for(let i=0;i<ring.length;i++)connect(m,ring[i]!,ring[(i+1)%ring.length]!);const route=[c(0,3),c(1,3),c(2,3),c(2,2),c(3,2),c(4,2),c(5,2),c(6,2),c(7,2),c(7,1),c(6,1),c(5,1),c(4,1),c(3,1),c(2,1),c(1,1),c(0,1),c(0,0)];for(let i=1;i<route.length;i++)connect(m,route[i-1]!,route[i]!);return freeCellLayout(withPortals(m,[{cell:c(0,3),side:'west'},{cell:c(0,0),side:'north'}]));}
export function freeRouteTrapFixture(){const m=emptyMaze({columns:11,rows:13,corridorWidth:2,algorithm:'prim',seed:'far',extraConnections:0}),parent=m.passages.map((_,i)=>i);const root=(n:number):number=>parent[n]===n?n:(parent[n]=root(parent[n]!)),add=(a:number,b:number)=>{if(root(a)!==root(b)){parent[root(a)]=root(b);connect(m,a,b);}};const chain=(p:number[][])=>{for(let i=1;i<p.length;i++){const[x,z]=p[i-1]!,[tx,tz]=p[i]!;let a=z!*11+x!;const target=tz!*11+tx!,step=x===tx?Math.sign(tz!-z!)*11:Math.sign(tx!-x!);while(a!==target){add(a,a+step);a+=step;}}};chain([[0,6],[2,6],[2,1],[5,1],[5,12]]);chain([[2,6],[2,10],[3,10],[3,11]]);for(let a=0;a<m.passages.length;a++)for(const b of neighbors(m,a))if(a!==124&&b!==124)add(a,b);return freeCellLayout(withPortals({...m,entrance:{cell:66,side:'west'},exit:{cell:137,side:'south'}},[{cell:66,side:'west'},{cell:137,side:'south'}]),0,1.5);}
